let frontmatter = {
    "title": "Fumadocs 12.0.5",
    "description": "After the release of Fumadocs 12",
    "author": "Fuma Nama",
    "date": new Date(1718236800000)
};
let lastModified = new Date(1747962302000);
let structuredData = {
    "contents": [
        {
            "heading": "some-improvements",
            "content": "After releasing Fumadocs 12, some improvements were made to the new UI."
        },
        {
            "heading": "toc-popover",
            "content": "Previously, this was only available on larger devices. Now, it's collapsed to a popover on smaller devices."
        },
        {
            "heading": "links-menu",
            "content": "To make the sidebar look even better, we moved navigation links to the links menu (the three-dots button at the top corner)."
        },
        {
            "heading": "links-menu",
            "content": "The recommended design is:"
        },
        {
            "heading": "links-menu",
            "content": "Docs related links: Use <RootToggle /> or include it in page trees."
        },
        {
            "heading": "links-menu",
            "content": "Other links: Use the Links API of docs layout."
        },
        {
            "heading": "breadcrumbs",
            "content": "Removed the duplicated page name from breadcrumbs, now it only shows the folder names.\nAlso, you can enable includeSeparators to show separators on your breadcrumbs component."
        },
        {
            "heading": "breadcrumbs",
            "content": "The new breadcrumbs look cleaner and match the design even better."
        },
        {
            "heading": "adaption",
            "content": "Some docs sites such as https://yeecord.com and https://turbo.build have adopted the new UI, I'm very excited about it.\nRemoving the navbar seemed to be a very risky move to me, almost no documentation framework has done it, and I was expecting some complaints about the new design."
        },
        {
            "heading": "adaption",
            "content": "Luckily, most people are satisfied with the new UI.\nThe new design was originally inspired by Arc, their sidebar looked very impressive to me.\nAlthough I soon discovered the docs site of Linear also doesn't have a navbar, Arc is still the first inspiration of the redesign."
        },
        {
            "heading": "adaption",
            "content": "I'm grateful that many people gave me their feedback about the new design, so that I can keep making Fumadocs a better framework to use.\nLet's make better docs."
        }
    ],
    "headings": [
        {
            "id": "some-improvements",
            "content": "Some Improvements"
        },
        {
            "id": "toc-popover",
            "content": "TOC Popover"
        },
        {
            "id": "links-menu",
            "content": "Links Menu"
        },
        {
            "id": "breadcrumbs",
            "content": "Breadcrumbs"
        },
        {
            "id": "adaption",
            "content": "Adaption"
        }
    ]
};
